// Copies team-owned JSON (i18n, fixtures, thresholds, labels) into src/generated so the
// frontend always builds from the same files the backend serves. Run automatically by
// predev/prebuild/pretest. Never edit src/generated by hand.
import { cpSync, existsSync, mkdirSync, readdirSync, writeFileSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const out = join(here, '..', 'src', 'generated');
mkdirSync(join(out, 'locales'), { recursive: true });
mkdirSync(join(out, 'fixtures'), { recursive: true });

for (const lang of ['en', 'hi', 'mr']) {
  cpSync(join(root, 'content', 'i18n', `${lang}.json`), join(out, 'locales', `${lang}.json`));
}
for (const f of readdirSync(join(root, 'shared', 'fixtures'))) {
  if (f.endsWith('.json')) cpSync(join(root, 'shared', 'fixtures', f), join(out, 'fixtures', f));
}
const thresholds = join(root, 'ml', 'export', 'thresholds.json');
writeFileSync(
  join(out, 'thresholds.json'),
  existsSync(thresholds)
    ? readFileSync(thresholds)
    : JSON.stringify({ unknown_photo: 0.45, likely_high: 0.7, likely_high_margin: 0.3, likely_medium: 0.5 }),
);
cpSync(join(root, 'shared', 'labels.json'), join(out, 'labels.json'));
// Only used in VITE_USE_FIXTURES=1 mode (no backend).
cpSync(join(root, 'content', 'schemes.json'), join(out, 'schemes.json'));
console.log('sync-content: copied i18n, fixtures, thresholds, labels, schemes');
